cardHeader:
COMPONENT Property 1=center-header V
  FRAME content H
    INSTANCE plus {visible:left icon}
    TEXT Title "Card Title" {visible:title lg}
    TEXT Title "Card Title" {visible:Title sm}
    INSTANCE plus {visible:right icon}

textField:
COMPONENT V 332x104
  FRAME Label {visible:has label} H
    TEXT Floating label {characters:field label}
    TEXT Mandatory "*" {visible:is required}
    INSTANCE information-outline 2 {visible:has user guidance}
  FRAME inputBox H fill/hug 332x48
    FRAME icon-right {visible:icon-left} > INSTANCE calendar-month-outline
    TEXT Input text {characters:content} fill/hug
    FRAME icon-right {visible:icon-right} > INSTANCE calendar-month-outline
  FRAME Assistive text {visible:Assistive Text}
    TEXT Text {characters:assistive text}

textArea:
COMPONENT V 332x192
  FRAME Label {visible:has label}
    TEXT Floating label {characters:label text}
    TEXT Mandatory {visible:is required}
  FRAME inputBox V fill/fill 332x136
    FRAME content > TEXT Input text {characters:content}
    FRAME resize handler (drag horizontal, drag corner)
  FRAME Assistive text {visible:assistive text} > TEXT {characters:assistive content}

autocomplete:
COMPONENT V 414x104
  FRAME Label {visible:has label} > TEXT {characters:label content}, Mandatory {visible:is required}
  FRAME inputBox H 414x48
    INSTANCE icon/action/search {visible:left icon}
    TEXT Input text {characters:content}
    INSTANCE menu-down {visible:has arrow}
    INSTANCE magnify 1 {visible:has icon}
  FRAME Assistive text {visible:assistive text}

listItem:
COMPONENT status=Default H 912x48
  FRAME Icon Container {visible:has icon} > INSTANCE {swap:Instance}
  FRAME label V
    TEXT Label {characters:label}
    TEXT description {visible:bottom description}
  TEXT Label {visible:right description}
  INSTANCE Switch Toggle {visible:has toggle}
  FRAME Icon Container {visible:right icon}
  FRAME Icon Container {visible:directional}

button:
COMPONENT H
  INSTANCE plus {visible:icon-left}
  TEXT Button {visible:uppercase, characters:Text}
  TEXT Button {visible:title case, characters:Text}
  INSTANCE plus {visible:icon right}
